    *seed = GFROR13(*seed);
    if (scaled > 0.0001) {
        double result = fmod((double)*seed, scaled);
        return (float)(result * (1.0 / 65536.0));
    }
    return 0.0f;
}

class C3DVector { public: float X, Y, Z; };

class CPerlinNoise {
public:
    unsigned long IndexTable[256];                      // +0x000
    C3DVector     VectorTable[256];                     // +0x400
