    unsigned long i;
    for (i = 0; i < 256; ++i)
        IndexTable[i] = i;
    for (i = 0; i < 256; ++i) {
        seed = GFROR13(seed * 0x24A1 + 0x24DF);
        unsigned long swap = IndexTable[i];
        IndexTable[i] = IndexTable[seed & 0xFF];
        IndexTable[seed & 0xFF] = swap;
