    for (i = 0; i < 256; ++i) {
        C3DVector& v = VectorTable[i];
        v.X = GFFloatRandom(2.0f, &seed) - 1.0f;
        v.Y = GFFloatRandom(2.0f, &seed) - 1.0f;
